from typing import List

def solve(n: int, a: List[int]) -> List[int]:
    total_sum = sum(a)
    if total_sum % 2 == 0:
        return [-1]

    a.sort()
    left_sum = 0
    right_sum = total_sum
    result = []

    for i in range(2 * n):
        if left_sum < right_sum:
            left_sum += a[i]
            result.append(a[i])
        else:
            right_sum -= a[i]
            result.append(a[i])

    if left_sum == right_sum:
        return [-1]

    return result

