        def backtrack(start, current_sum, used):
            if current_sum == target:
                return True
            if current_sum > target:
                return False
            for i in range(start, len(arr)):
                if not used[i]:
                    used[i] = True
                    if backtrack(i + 1, current_sum + arr[i], used):
                        return True
                    used[i] = False
            return False

