            if current_sum > target:
                return None
            for i in range(start, len(arr)):
                if not used[i]:
                    used[i] = True
                    half.append(arr[i])
                    result = backtrack(i + 1, current_sum + arr[i], half)
                    if result is not None:
                        return result
                    half.pop()
